import collections,datetime,functools,hashlib,itertools,json,os,pathlib,platform,resource,signal,subprocess,sys,tempfile,time
START=time.monotonic();resource.setrlimit(resource.RLIMIT_CPU,(120,120));resource.setrlimit(resource.RLIMIT_AS,(1<<30,1<<30));signal.alarm(120)
ROOT=pathlib.Path(os.environ.get('RULE30_REPLAY_ROOT','/home/ryan/rule30-lab'))
OUT=pathlib.Path(os.environ.get('RULE30_REPLAY_OUTPUT',str(ROOT/'results/problem1/20260905_core_overlap_independent.json')))
def sha(b):return hashlib.sha256(b).hexdigest()
def canon(v):return json.dumps(v,sort_keys=True,separators=(',',':')).encode()
inputs={}
def read(p):
 b=(ROOT/p).read_bytes();inputs[p]=sha(b);return json.loads(b)
head=read('results/problem1/20260905_frontier_head_independent.json')['result_summary']
primary=read('results/problem1/20260905_core_overlap_primary.json')
runs={}
for name,item in primary['runs'].items():
 raw=item['raw_json_text'].encode();assert sha(raw)==item['raw_sha256'];r=json.loads(raw);runs[name]=r
 assert sha(r['source_text'].encode())==r['result_hashes']['source_sha256']
 assert sha(json.dumps(r['result_summary'],sort_keys=True).encode())==r['result_hashes']['result_summary_sha256']
 for p,h in r['provenance']['inputs'].items():
  b=(ROOT/p).read_bytes();assert sha(b)==h;inputs[p]=h
assert sha(primary['source_text'].encode())==primary['result_hashes']['source_sha256']
assert sha(canon(primary['result_summary']))==primary['result_hashes']['result_summary_sha256']
@functools.lru_cache(None)
def T(x):
 b=[(x>>i)&1 for i in range(x.bit_length()+2)]
 return sum((b[i]^((b[i-1] if i else 0)|(b[i-2] if i>1 else 0)))<<i for i in range(len(b)))
def A(x):return T(x)>>2
def G(g,x):return T(x) if g=='t' else T(x)^1 if g=='u' else T(2*x+1)>>1
def I(x):return int(x%64 in (0,5))
def pref(root,w):
 v=[root]
 for g in w:v.append(G(g,v[-1]))
 return v
def H(root,w):return ''.join('tupp'[x%4] for x in pref(root,w)[1:])
def omega(x,g):return int((x%16,g) in [(0,'t'),(1,'u')])
def costs(root,w):return [omega(x,g) for x,g in zip(pref(root,w),w)]
def gate(x):return 'u' if x%16==7 else 't' if x%16==11 else None
def orbit(x,cap):
 xs=[x];w=''
 for _ in range(cap):
  g=gate(x)
  if not g:break
  w+=g;x=G(g,A(x));xs.append(x)
 return xs,w
def Ap(x,s):
 for _ in range(s):x=A(x)
 return x
def D(x,s):return sum(I(Ap(x>>(2*d),s-1-d)) for d in range(s))
def admissible(w):return not any(z in w for z in ('uu','ttttt','ututtu'))
stored={(r['phase'],r['h']):r for r in head['frontier_core_rows']};coredata={};tables=[];image_sets_checked=0
for phase,root in [('p',3),('u',1)]:
 O={root}
 for h in range(1,9):
  cur=O;tau=0;counts=[len(cur)]
  while True:
   nxt={A(x) for x in cur};image_sets_checked+=1;assert nxt<=cur
   if nxt==cur:break
   cur=nxt;tau+=1;counts.append(len(cur))
  if (phase,h) in stored:
   sr=stored[phase,h];assert sorted(O)==sr['initial_frontier'] and sorted(cur)==sr['core'];assert tau==sr['stabilization_age'] and counts==sr['image_counts']
  coredata[phase,h]={'core':sorted(cur),'tau':tau}
  if h>=2:
   C=sorted(cur);old=coredata[phase,h-1]['core'];self_b=next(b for b in range(2*h+1) if len({x%(1<<b) for x in C})==len(C));adj_b=next(b for b in range(2*h+1) if {x%(1<<b) for x in C}.isdisjoint({x%(1<<b) for x in old}))
   tables.append({'phase':phase,'h':h,'core':C,'previous_core':old,'tau':tau,'previous_tau':coredata[phase,h-1]['tau'],'self_b':self_b,'adjacent_b':adj_b,'self_k_min':h+tau,'adjacent_k_min':h+max(tau,coredata[phase,h-1]['tau']),'self_r_minus_k':-h+(self_b+1)//2-1,'adjacent_L_minus_k':-h+(adj_b+1)//2})
  if h<8:O={G(g,x) for x in O for g in 'tup'}
# Same completed word domains as Muse; direct H costs instead of positional shortcut.
counters=[];scanned={};positives=0;step_hist=collections.Counter();witness=None
for s,n in [(1,6),(2,7)]:
 found=[];total=0
 for phase,root in [('p',3),('u',1)]:
  for letters in itertools.product('tup',repeat=n):
   w=''.join(letters);vs=pref(root,w);x=vs[-1];hw=w
   for _ in range(s):hw=H(root,hw)
   cc=costs(root,hw);total+=1;assert cc[4]==I(Ap(vs[5],s-1))
   if cc[4]!=1:continue
   xs,br=orbit(x,s+1)
   if s==1:
    positives+=1;step_hist[len(br)]+=1;assert x%64 in [0,1,3,26,27] and len(br)<2
   if len(br)==s+1 and admissible(br):found.append({'phase':phase,'word':w,'endpoint':x,'branches':br})
 found.sort(key=lambda r:(r['phase'],r['endpoint'],r['word']))
 scanned['s'+str(s)]={'words_scanned':total,'eligible_counters':len(found)}
 if found:counters=found;break
assert counters==runs['forced_head']['counters_min_age']
rs=runs['forced_head']['result_summary'];assert scanned==rs['scanned'] and counters[0]==rs['smallest'];assert positives==rs['s1_all_input']['fifth_cost_positives'] and [list(x) for x in sorted(step_hist.items())]==rs['s1_all_input']['forced_step_histogram']
r=counters[0];root=3;w=r['word'];vs=pref(root,w);xs,br=orbit(vs[-1],3);hw=H(root,H(root,w));cw=costs(root,hw);fw=H(root,H(root,w)+br[0])+br[1]
witness={'phase':'p','word_from_zero':'p'+w,'n':len(w),'s':2,'prefixes':vs,'endpoint':vs[-1],'observed_branches':br,'states':xs,'H2_word_from_zero':'p'+hw,'H2_costs':cw,'C':sum(cw),'D':D(vs[-1],2),'gap':sum(cw)-D(vs[-1],2),'prescribed_time2_word_from_zero':'p'+fw,'prescribed_time2_W':sum(costs(root,fw))}
assert witness['gap']==1 and witness['observed_branches']=='ttu' and witness['endpoint']==56939
overlap=runs['overlap']['result_summary']
assert overlap['regen_match_16_of_16']
for row in tables:
 key=row['phase']+' h'+str(row['h']);sc=overlap['self_table'][key];ac=overlap['adj_table'][key]
 assert sc=={'b':row['self_b'],'tau':row['tau'],'k':row['self_k_min'],'r':max(1,row['self_k_min']+row['self_r_minus_k'])}
 assert ac=={'b':row['adjacent_b'],'tau':max(row['tau'],row['previous_tau']),'k':row['adjacent_k_min'],'L':row['adjacent_k_min']+row['adjacent_L_minus_k']}

summary={'completed':True,'failures':[],'core_levels_checked':16,'image_sets_checked':image_sets_checked,'overlap_tables':tables,'scanned_forced_head':scanned,'forced_head_counters':counters,'s1_positive_count':positives,'s1_step_histogram':[list(x) for x in sorted(step_hist.items())],'smallest_witness':witness,'original_payload_source_summary_input_hashes_verified':True}
source=pathlib.Path(__file__).read_bytes();record={'experiment_id':'problem1-core-overlap-independent-20260905','timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'git_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'question':'problem1','hypothesis':'Existing periodic leading blocks have the asserted self/adjacent overlaps; forced continuation does not erase the omitted fifth position.','backend':'python-cell-rule-odd-section-and-direct-H','parameters':{'phases':['p','u'],'frontier_levels':[1,8],'overlap_levels':[2,8],'forced_head_domains':[[1,6],[2,7]],'forced_head_age3':'not run: counter at age2','cpu_seconds_limit':120,'wall_seconds_limit':120,'address_space_bytes':1<<30},'hardware':{'machine':platform.machine(),'cpu_count':os.cpu_count(),'peak_rss_kib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss},'software':{'python':sys.version,'platform':platform.platform()},'runtime_seconds':time.monotonic()-START,'inputs':inputs,'source_text':source.decode(),'result_hashes':{'source_sha256':sha(source),'result_summary_sha256':sha(canon(summary))},'result_summary':summary,'status':'finite-exhaustive','interpretation':'Finite base calculations and stated forced-head scans pass; all-depth consequences require the separate leading-block proof.','proof_scope':'Only the declared finite cores, residue maps and two completed word lengths.','limitations':['No larger periodic core, frontier or occurrence census.','No sufficiency of decoded leading-core candidate for ordinary membership.','No actual return exclusion or Problem1 proof.']}
with tempfile.NamedTemporaryFile('w',dir=OUT.parent,delete=False) as f:
 json.dump(record,f,sort_keys=True,indent=2);f.write('\n');f.flush();os.fsync(f.fileno());tmp=f.name
